<https://example.org/openevidence/questions/q_addison_disease_efficacy> a holon:ClinicalQuestionHolon ;
    holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_addison_disease_efficacy-bou> ;
    holon:hasContextGraph <https://example.org/openevidence/questions/q_addison_disease_efficacy-con> ;
    holon:hasInteriorGraph <https://example.org/openevidence/questions/q_addison_disease_efficacy-int> ;
    holon:hasProjectionGraph <https://example.org/openevidence/questions/q_addison_disease_efficacy-pro> ;
    oe:answerText "Prednisone is an inconclusive treatment."^^xsd:string ;
    oe:questionText "Is prednisone effective for Addison's disease?"^^xsd:string ;
    oe:belongsToSpecialty "Endocrinology" .

<https://example.org/openevidence/drugs/prednisone> oe:treats <https://example.org/openevidence/diseases/addison_disease> | confidence=0.38 | level=Level-4 | source=<https://example.org/openevidence/sources/36102024> | effectiveness=inconclusive ;
<https://example.org/openevidence/drugs/atorvastatin> oe:treats <https://example.org/openevidence/diseases/coronary_artery_disease> | confidence=0.89 | level=Level-1B | source=<https://example.org/openevidence/sources/37852649> | effectiveness=effective ;
<https://example.org/openevidence/drugs/furosemide> oe:treats <https://example.org/openevidence/diseases/aortic_stenosis> | confidence=0.56 | level=Level-3 | source=<https://example.org/openevidence/sources/37495229> | effectiveness=effective ;
<https://example.org/openevidence/drugs/prednisone> oe:treats <https://example.org/openevidence/diseases/myasthenia_gravis> | confidence=0.22 | level=Level-5 | source=<https://example.org/openevidence/sources/38117543> | effectiveness=inconclusive ;
<https://example.org/openevidence/drugs/prednisone> oe:treats <https://example.org/openevidence/diseases/idiopathic_pulmonary_fibrosis> | confidence=0.92 | level=Level-1B | source=<https://example.org/openevidence/sources/38459338> | effectiveness=effective .
